package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

// ── capsule workflow ─────────────────────────────────────────────────────────
// CLI.md 3.4. operationIds: workflowsList workflowDispatch (+ runsList/runGet
// for --wait).

// capsuleCLISecurity is the npm version the generated security workflows
// install: the first one that has `capsule security sarif upload`.
const capsuleCLISecurity = "0.7.0"

var workflowTemplates = map[string]string{
	"ci-node": `# Generated by ` + "`capsule workflow new --template ci-node`" + `. Syntax compatible with GitHub Actions.
name: CI
on:
  push:
    branches: [main]
  pull_request:
    branches: [main]
  workflow_dispatch:
jobs:
  test:
    name: Lint, tests and build
    runs-on: docker
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: '20'
      - run: npm ci
      - run: npm run lint --if-present
      - run: npm test --if-present
      - run: npm run build --if-present
`,
	"sast": `# Generated by ` + "`capsule workflow new --template sast`" + `. SAST with Semgrep; findings go to Capsule Security as SARIF.
# Secret: CAPSULE_SECURITY_TOKEN, a token with scope security:write limited to this project:
#   capsule tokens create --name forgejo-sarif --scope security:write --project <project-id>
# Variable: CAPSULE_API_URL, secrets CAPSULE_ORG_ID and CAPSULE_PROJECT_ID.
name: SAST
on:
  push:
    branches: [main]
  pull_request:
    branches: [main]
  workflow_dispatch:
env:
  SEMGREP_VERSION: "` + forgejoSemgrepVersion + `"
  CAPSULE_CLI_VERSION: "` + capsuleCLISecurity + `"
jobs:
  semgrep:
    name: Semgrep
    runs-on: docker
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with:
          python-version: '3.12'
      - uses: actions/setup-node@v4
        with:
          node-version: '20'
      - run: pip install "semgrep==${SEMGREP_VERSION}"
      - run: semgrep scan --config p/ci --sarif --output semgrep.sarif --metrics=off
      - run: npm install -g @kyntocg/capsule-cli@${CAPSULE_CLI_VERSION}
      - name: Upload findings to Capsule Security
        env:
          CAPSULE_TOKEN: ${{ secrets.CAPSULE_SECURITY_TOKEN }}
          CAPSULE_ORG_ID: ${{ secrets.CAPSULE_ORG_ID }}
          CAPSULE_PROJECT_ID: ${{ secrets.CAPSULE_PROJECT_ID }}
          CAPSULE_API_URL: ${{ vars.CAPSULE_API_URL }}
        run: capsule security sarif upload semgrep.sarif --sha "$GITHUB_SHA" --ref "$GITHUB_REF_NAME" --tool semgrep
`,
	"gitleaks": `# Generated by ` + "`capsule workflow new --template gitleaks`" + `. Secret scanning; findings go to Capsule Security as SARIF.
# Secrets: CAPSULE_SECURITY_TOKEN (scope security:write), CAPSULE_ORG_ID, CAPSULE_PROJECT_ID. Variable: CAPSULE_API_URL.
name: Secrets
on:
  push:
    branches: [main]
  pull_request:
    branches: [main]
  workflow_dispatch:
env:
  GITLEAKS_VERSION: "` + forgejoGitleaksVersion + `"
  CAPSULE_CLI_VERSION: "` + capsuleCLISecurity + `"
jobs:
  gitleaks:
    name: Gitleaks
    runs-on: docker
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 0
      - uses: actions/setup-node@v4
        with:
          node-version: '20'
      - name: Install gitleaks
        run: curl -sSfL "https://github.com/gitleaks/gitleaks/releases/download/v${GITLEAKS_VERSION}/gitleaks_${GITLEAKS_VERSION}_linux_x64.tar.gz" | tar -xz -C /usr/local/bin gitleaks
      - name: Scan history
        run: gitleaks git --redact --no-banner --report-format sarif --report-path gitleaks.sarif --exit-code 0 .
      - run: npm install -g @kyntocg/capsule-cli@${CAPSULE_CLI_VERSION}
      - name: Upload findings to Capsule Security
        env:
          CAPSULE_TOKEN: ${{ secrets.CAPSULE_SECURITY_TOKEN }}
          CAPSULE_ORG_ID: ${{ secrets.CAPSULE_ORG_ID }}
          CAPSULE_PROJECT_ID: ${{ secrets.CAPSULE_PROJECT_ID }}
          CAPSULE_API_URL: ${{ vars.CAPSULE_API_URL }}
        run: capsule security sarif upload gitleaks.sarif --sha "$GITHUB_SHA" --ref "$GITHUB_REF_NAME" --tool gitleaks
`,
	"trivy": `# Generated by ` + "`capsule workflow new --template trivy`" + `. Filesystem/IaC scan; findings go to Capsule Security as SARIF.
# Secrets: CAPSULE_SECURITY_TOKEN (scope security:write), CAPSULE_ORG_ID, CAPSULE_PROJECT_ID. Variable: CAPSULE_API_URL.
name: Trivy
on:
  push:
    branches: [main]
  pull_request:
    branches: [main]
  workflow_dispatch:
env:
  TRIVY_VERSION: "` + forgejoTrivyVersion + `"
  CAPSULE_CLI_VERSION: "` + capsuleCLISecurity + `"
jobs:
  trivy:
    name: Trivy
    runs-on: docker
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: '20'
      - name: Install trivy
        run: curl -sSfL "https://github.com/aquasecurity/trivy/releases/download/v${TRIVY_VERSION}/trivy_${TRIVY_VERSION}_Linux-64bit.tar.gz" | tar -xz -C /usr/local/bin trivy
      - name: Scan repository
        run: trivy fs --scanners vuln,secret,misconfig --severity HIGH,CRITICAL --ignore-unfixed --format sarif --output trivy.sarif .
      - run: npm install -g @kyntocg/capsule-cli@${CAPSULE_CLI_VERSION}
      - name: Upload findings to Capsule Security
        env:
          CAPSULE_TOKEN: ${{ secrets.CAPSULE_SECURITY_TOKEN }}
          CAPSULE_ORG_ID: ${{ secrets.CAPSULE_ORG_ID }}
          CAPSULE_PROJECT_ID: ${{ secrets.CAPSULE_PROJECT_ID }}
          CAPSULE_API_URL: ${{ vars.CAPSULE_API_URL }}
        run: capsule security sarif upload trivy.sarif --sha "$GITHUB_SHA" --ref "$GITHUB_REF_NAME" --tool trivy
`,
}

// resolveWorkflow matches a workflow by id, name or file path/name.
func resolveWorkflow(cmd *cobra.Command, ref string) (string, error) {
	p, err := gp(cmd, "/workflows")
	if err != nil {
		return "", err
	}
	var raw any
	if _, err := apiDo("GET", p, nil, &raw, nil); err != nil {
		return "", err
	}
	items, _ := pageOf(raw)
	var hits []rec
	for _, w := range items {
		if sv(w, "id") == ref || sv(w, "name") == ref || sv(w, "path") == ref || strings.HasSuffix(sv(w, "path"), "/"+ref) {
			hits = append(hits, w)
		}
	}
	switch len(hits) {
	case 0:
		return "", usageErr("no workflow matches %q (see `capsule workflow list`)", ref)
	case 1:
		return sv(hits[0], "id"), nil
	}
	return "", usageErr("%q matches %d workflows; use the id", ref, len(hits))
}

func init() {
	list := leaf("list", "List the workflows of the repository", cobra.NoArgs, func(cmd *cobra.Command, args []string) error {
		p, err := gp(cmd, "/workflows")
		if err != nil {
			return err
		}
		var raw any
		if _, err := apiDo("GET", p, nil, &raw, nil); err != nil {
			return err
		}
		if done, err := emit(cmd, raw); done || err != nil {
			return err
		}
		items, _ := pageOf(raw)
		if quietIDs(cmd, items) {
			return nil
		}
		t := newTable(cmd, "ID", "NAME", "PATH", "TRIGGERS", "STATE")
		for _, w := range items {
			t.row(sv(w, "id"), sv(w, "name"), sv(w, "path"), sv(w, "triggers"), sv(w, "state"))
		}
		return t.flush()
	})
	list.Aliases = []string{"ls"}
	list.Flags().BoolP("quiet", "q", false, "Print only IDs")

	run := leaf("run WORKFLOW", "Dispatch a workflow (workflow_dispatch)", cobra.ExactArgs(1), func(cmd *cobra.Command, args []string) error {
		f := cmd.Flags()
		id, err := resolveWorkflow(cmd, args[0])
		if err != nil {
			return err
		}
		ref, _ := f.GetString("ref")
		if ref == "" {
			rp, _ := gp(cmd, "/repo")
			var repo rec
			if _, err := apiDo("GET", rp, nil, &repo, nil); err != nil {
				return err
			}
			if ref = sv(repo, "default_branch"); ref == "" {
				return usageErr("--ref is required (the repository reports no default branch)")
			}
		}
		inputs := map[string]string{}
		kvs, _ := f.GetStringArray("field")
		for _, kv := range kvs {
			k, v, err := parseKeyVal(kv)
			if err != nil {
				return usageErr("-f: %v", err)
			}
			inputs[k] = v
		}
		body := rec{"ref": ref}
		if len(inputs) > 0 {
			body["inputs"] = inputs
		}
		p, err := gp(cmd, "/workflows/"+seg(id)+"/dispatch")
		if err != nil {
			return err
		}
		started := time.Now().Add(-10 * time.Second)
		var out rec
		if _, err := apiDo("POST", p, body, &out, idemHeaders(cmd, args)); err != nil {
			return err
		}
		fmt.Printf("Workflow %s dispatched on %s.\n", args[0], ref)
		wait := waitDuration(cmd)
		if wait == 0 {
			return nil
		}
		runID := sv(out, "id", "run_id")
		if runID == "" {
			lp, _ := gp(cmd, "/runs"+q("workflow", id, "branch", ref, "event", "workflow_dispatch"))
			err := pollUntil(wait, "the run to appear", func() (bool, string, error) {
				var raw any
				if _, err := apiDo("GET", lp, nil, &raw, nil); err != nil {
					return false, "", err
				}
				items, _ := pageOf(raw)
				for _, r := range items {
					if t, e := time.Parse(time.RFC3339, sv(r, "created_at")); e == nil && t.After(started) {
						runID = sv(r, "id")
						return true, "run " + runID, nil
					}
				}
				return false, "waiting for the run", nil
			})
			if err != nil {
				return err
			}
		}
		fmt.Printf("Run %s\n", runID)
		return watchRun(cmd, runID, wait, true)
	})
	run.Flags().String("ref", "", "Branch or tag (default: the default branch)")
	run.Flags().StringArrayP("field", "f", nil, "Workflow input key=value (repeatable)")
	addWait(run, "the run")
	addIdem(run)

	nw := userLeaf("new", "Write a ready-to-use workflow into .forgejo/workflows", cobra.NoArgs, func(cmd *cobra.Command, args []string) error {
		f := cmd.Flags()
		tpl, _ := f.GetString("template")
		force, _ := f.GetBool("force")
		toStdout, _ := f.GetBool("print")
		root, _ := os.Getwd()
		if d := os.Getenv("CAPSULE_CWD"); d != "" {
			root = d
		}
		if tpl == "deploy" {
			return ciInitForgejo(cmd, "auto", "main", "", force, toStdout, strings.ReplaceAll(root, "\\", "/"))
		}
		body, ok := workflowTemplates[tpl]
		if !ok {
			return usageErr("unknown --template %q (ci-node, sast, gitleaks, deploy, trivy)", tpl)
		}
		if toStdout {
			fmt.Print(body)
			return nil
		}
		dir := filepath.Join(root, ".forgejo", "workflows")
		file := filepath.Join(dir, tpl+".yml")
		if _, err := os.Stat(file); err == nil && !force {
			return usageErr("%s already exists (use --force to overwrite, or --print to preview)", file)
		}
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(file, []byte(body), 0o644); err != nil {
			return err
		}
		fmt.Printf("Wrote .forgejo/workflows/%s.yml\n", tpl)
		if tpl != "ci-node" {
			fmt.Printf("  note: it installs @kyntocg/capsule-cli@%s, the first version with `capsule security sarif upload`.\n", capsuleCLISecurity)
		}
		return nil
	})
	nw.Flags().String("template", "ci-node", "ci-node, sast, gitleaks, deploy or trivy")
	nw.Flags().Bool("force", false, "Overwrite an existing file")
	nw.Flags().Bool("print", false, "Print instead of writing")

	g := group("workflow", "Actions workflows: list, run, new", list, run, nw)
	g.Aliases = []string{"workflows"}
	rootCmd.AddCommand(g)
}
